function paint(rows: string[], pal: Record<string, string>): HTMLCanvasElement {
  const w = Math.max(...rows.map(r => r.length));
  const p = new PixelCanvas(w, rows.length);
  rows.forEach((r, y) => [...r].forEach((ch, x) => ch !== '.' && pal[ch] && p.px(x, y, pal[ch])));
  return p.outline('auto', 0.22).toCanvas();
}

/** HD idle frames of an NPC (or of a wanderer such as the grey postman). */
export function npcFrames(id: NpcId | 'postman'): HTMLCanvasElement[] {
  if (id === 'aldric') return ALDRIC.map(f => paint(f, ALDRIC_PAL));
  const p = PEOPLE[id];
  return p.frames.map(f => paint(f, p.pal));
}

